test("stream end in a later render removes transient streaming indicators", () => {
  const container = document.createElement("div");
  const LiveChatView = LoadChatView();
  const handle = LiveChatView.create(container, null);
  LiveChatView._flushFrames();

  applyServerMessage(handle.state, {
    type: "events",
    events: [
      { type: "TEXT_MESSAGE_START", messageId: "stream-end", role: "assistant" },
      { type: "TEXT_MESSAGE_CONTENT", messageId: "stream-end", delta: "done" },
      { type: "REASONING_MESSAGE_START", messageId: "reason-end" },
      { type: "REASONING_MESSAGE_CONTENT", messageId: "reason-end", delta: "thinking" },
    ],
  });
  renderChat(handle);

  const assistantEntry = handle.messageNodes.get("stream-end");
  const reasoningEntry = handle.messageNodes.get("reason-end");
  assert.ok(assistantEntry);
  assert.ok(reasoningEntry);
  assert.equal(
    assistantEntry.content.innerHTML.includes("agui-chat-streaming"),
    true
  );
  assert.ok(reasoningEntry.spinner);
  assert.equal(reasoningEntry.spinner.style.display || "", "");

  applyServerMessage(handle.state, {
    type: "events",
    events: [
      { type: "TEXT_MESSAGE_END", messageId: "stream-end" },
      { type: "REASONING_MESSAGE_END", messageId: "reason-end" },
    ],
  });
  renderChat(handle);

  assert.equal(
    assistantEntry.content.innerHTML.includes("agui-chat-streaming"),
    false
  );
  assert.equal(reasoningEntry.spinner.style.display, "none");
});

test("tool and reasoning panels toggle expanded state", () => {
  const container = document.createElement("div");
  const LiveChatView = LoadChatView();
  const handle = LiveChatView.create(container, null);
  LiveChatView._flushFrames();

  applyServerMessage(handle.state, {
    type: "events",
    events: [
      {
        type: "TEXT_MESSAGE_START",
        messageId: "asst",
        role: "assistant",
      },
      { type: "TEXT_MESSAGE_END", messageId: "asst" },
      {
        type: "TOOL_CALL_START",
        toolCallId: "tc-1",
        toolCallName: "grep",
        parentMessageId: "asst",
      },
      {
        type: "TOOL_CALL_RESULT",
        toolCallId: "tc-1",
        messageId: "tool-msg",
        content: "found it",
      },
      { type: "TOOL_CALL_END", toolCallId: "tc-1" },
      { type: "REASONING_MESSAGE_START", messageId: "reason-1" },
      { type: "REASONING_MESSAGE_CONTENT", messageId: "reason-1", delta: "hmm" },
      { type: "REASONING_MESSAGE_END", messageId: "reason-1" },
    ],
  });
  renderChat(handle);

  const toolBubble = handle.messageNodes.get("tool-msg")?.root;
  const reasonBubble = handle.messageNodes.get("reason-1")?.root;
  assert.ok(toolBubble);
  assert.ok(reasonBubble);
  assert.equal(toolBubble.classList.contains("agui-chat-bubble--expanded"), false);
  assert.equal(reasonBubble.classList.contains("agui-chat-bubble--expanded"), false);

  const toolHeader = toolBubble.children[0];
  toolHeader.click();
  assert.equal(toolBubble.classList.contains("agui-chat-bubble--expanded"), true);
  toolHeader.click();
  assert.equal(toolBubble.classList.contains("agui-chat-bubble--expanded"), false);

  const reasonHeader = reasonBubble.children[0];
  reasonHeader.click();
  assert.equal(reasonBubble.classList.contains("agui-chat-bubble--expanded"), true);
